package aaa;

// A method returning boolean and its bridge returning Object (Scala's
// BooleanSetting.value), assembled by hand since javac never bridges a
// primitive (generated by a small script; version 49):
//
//   class Flag implements Getter {
//     public boolean value() { return true; }
//     public synthetic bridge Object value() { return Boolean.valueOf(value()); }
//   }
//
// OpenLDK names methods without their return types, so it kept only the
// first, and callers through Getter got a bare 1, not a Boolean.
public class boxbridge extends ClassLoader
{
    public interface Getter { Object value(); }

    private static final byte[] FLAG = new byte[] {
        -54,-2,-70,-66,0,0,0,49,0,28,1,0,18,97,97,97,47,98,111,120,98,114,105,100,103,101,36,70,108,97,103,7,0,1,1,0,16,106,97,118,97,47,108,97,110,103,47,79,98,106,101,99,116,7,0,3,1,0,20,97,97,97,47,98,111,120,98,114,105,100,103,101,36,71,101,116,116,101,114,7,0,5,1,0,6,60,105,110,105,116,62,1,0,3,40,41,86,12,0,7,0,8,10,0,4,0,9,1,0,5,118,97,108,117,101,1,0,3,40,41,90,12,0,11,0,12,10,0,2,0,13,1,0,17,106,97,118,97,47,108,97,110,103,47,66,111,111,108,101,97,110,7,0,15,1,0,7,118,97,108,117,101,79,102,1,0,22,40,90,41,76,106,97,118,97,47,108,97,110,103,47,66,111,111,108,101,97,110,59,12,0,17,0,18,10,0,16,0,19,1,0,4,67,111,100,101,1,0,6,60,105,110,105,116,62,1,0,3,40,41,86,1,0,5,118,97,108,117,101,1,0,3,40,41,90,1,0,5,118,97,108,117,101,1,0,20,40,41,76,106,97,118,97,47,108,97,110,103,47,79,98,106,101,99,116,59,0,33,0,2,0,4,0,1,0,6,0,0,0,3,0,1,0,22,0,23,0,1,0,21,0,0,0,17,0,1,0,1,0,0,0,5,42,-73,0,10,-79,0,0,0,0,0,1,0,24,0,25,0,1,0,21,0,0,0,14,0,1,0,1,0,0,0,2,4,-84,0,0,0,0,16,65,0,26,0,27,0,1,0,21,0,0,0,20,0,1,0,1,0,0,0,8,42,-74,0,14,-72,0,20,-80,0,0,0,0,0,0
    };

    protected Class<?> findClass(String name) throws ClassNotFoundException
    {
        if (!name.equals("aaa.boxbridge$Flag")) throw new ClassNotFoundException(name);
        return defineClass(name, FLAG, 0, FLAG.length);
    }

    public static void main(String[] args) throws Exception
    {
        Class<?> c = new boxbridge().loadClass("aaa.boxbridge$Flag");
        Getter g = (Getter) c.getDeclaredConstructor().newInstance();
        Object v = g.value();
        Object z = c.getMethod("value").invoke(g);
        String result = (v instanceof Boolean) + " " + v + " " + z;
        System.out.println("true true true".equals(result) ? "OK" : "FAIL: " + result);
    }
}
